import { View, Text, FlatList, StyleSheet } from "react-native";

const DATA = [{ id: "a", name: "Áo" }, { id: "b", name: "Quần" }, { id: "c", name: "Mũ" }];

export default function App() {
  return (
    <FlatList
      data={DATA}
      keyExtractor={(item) => item.id}                       // key ổn định, không dùng index
      renderItem={({ item }) => <Text style={styles.row}>{item.name}</Text>}
      ItemSeparatorComponent={() => <View style={styles.sep} />}
      ListEmptyComponent={<Text>Chưa có sản phẩm</Text>}
    />
  );
}

const styles = StyleSheet.create({ row: { padding: 12 }, sep: { height: 1, backgroundColor: "#ddd" } });

